```python
# This code snippet is designed to address online abuse by implementing a basic filter system.

class OnlineAbuseFilter:
    def __init__(self, abusive_words):
        self.abusive_words = abusive_words

    def is_abusive(self, message):
        Check if the message contains any abusive words.
        for word in self.abusive_words:
            if word in message.lower():
                return True
        return False

    def filter_message(self, message):
        Replace abusive words in the message with asterisks.
        words = message.split()
        for i, word in enumerate(words):
            if word.lower() in self.abusive_words:
                words[i] = '*' * len(word)
        return ' '.join(words)

# Example usage
abusive_words_list = ['abuse', 'offensive', 'harmful']
filter_system = OnlineAbuseFilter(abusive_words_list)

message = This is an abusive message with offensive content.
if filter_system.is_abusive(message):
    print(Abusive content detected.)
    filtered_message = filter_system.filter_message(message)
    print(Filtered message:, filtered_message)
else:
    print(No abusive content detected.)
```

