// Smart Sprinklers System

// Function to determine if watering is needed
function isWateringNeeded(weatherForecast, soilMoistureLevel) {
    if (weatherForecast.includes('rain') || soilMoistureLevel > 70) {
        return false;
    }
    return true;
}

// Function to schedule watering
function scheduleWatering(time, duration) {
    console.log(`Watering scheduled at ${time} for ${duration} minutes.`);
}

// Function to activate sprinklers
function activateSprinklers() {
    console.log('Sprinklers activated.');
}

// Function to deactivate sprinklers
function deactivateSprinklers() {
    console.log('Sprinklers deactivated.');
}

// Main function to control the smart sprinkler system
function controlSmartSprinklers(weatherForecast, soilMoistureLevel, time, duration) {
    if (isWateringNeeded(weatherForecast, soilMoistureLevel)) {
        scheduleWatering(time, duration);
        activateSprinklers();
        setTimeout(deactivateSprinklers, duration * 60000); // Convert minutes to milliseconds
    } else {
        console.log('Watering not needed.');
    }
}

// Example usage
const weatherForecast = 'sunny';
const soilMoistureLevel = 50;
const time = '06:00 AM';
const duration = 30;

controlSmartSprinklers(weatherForecast, soilMoistureLevel, time, duration);
```

