// This code snippet addresses the theme of racial segregation and identity.
// It aims to highlight the importance of diversity and inclusion within a community.

function promoteDiversity(community) {
    let diverseRepresentation = 0;
    let totalMembers = community.length;

    community.forEach(member => {
        if (member.ethnicity !== 'majority') {
            diverseRepresentation++;
        }
    });

    let diversityPercentage = (diverseRepresentation / totalMembers) * 100;

    if (diversityPercentage < 30) {
        console.log(The community needs more diverse representation.);
    } else {
        console.log(The community has a healthy level of diversity.);
    }
}

let community = [
    { name: John, ethnicity: majority },
    { name: Sara, ethnicity: minority },
    { name: Lee, ethnicity: minority },
    { name: Anna, ethnicity: majority }
];

promoteDiversity(community);
