// The code below demonstrates a simple example of a qualitative analysis function
// that categorizes comments based on their sentiment and content.

function analyzeComment(comment) {
    // Define categories for qualitative analysis
    const categories = {
        positive: ['excellent', 'good', 'great', 'amazing', 'fantastic'],
        negative: ['bad', 'poor', 'terrible', 'awful', 'exploitative'],
        neutral: ['okay', 'fine', 'average', 'mediocre']
    };

    // Convert comment to lowercase for case-insensitive comparison
    const lowerCaseComment = comment.toLowerCase();

    // Analyze the comment to determine its category
    for (const [category, keywords] of Object.entries(categories)) {
        for (const keyword of keywords) {
            if (lowerCaseComment.includes(keyword)) {
                return category;
            }
        }
    }

    // Default to neutral if no keywords are found
    return 'neutral';
}

// Example usage
const comment = EXPLOITATION;
const category = analyzeComment(comment);
console.log(`The comment is categorized as: ${category}`);
```

