# Refined Thematic Framework for Analyzing Narratives Around Policing, Violence, and Racial Justice

themes = {
    Perceived Threat and Criminality: {
        Definition: The narrative portrays the individual as a danger to public safety, justified by their criminal history and actions during the incident.,
        Subthemes: {
            Criminal History: References to the individual's past offenses.,
            Immediate Danger: Descriptions of actions during the incident that posed a threat.
        }
    },
    Racial Bias and Public Response: {
        Definition: The narrative critiques the societal and media reactions to the incident, highlighting perceived racial disparities in public outrage and attention.,
        Subthemes: {
            Double Standards: Comparisons of how similar incidents involving different racial groups are perceived and discussed.,
            Media Influence: The role of media in shaping public perception based on racial identities.
        }
    },
    Criminalization and Dehumanization: {
        Definition: The narrative dehumanizes the individual by emphasizing their criminal history and past offenses to justify police actions.,
        Subthemes: {
            Vilification: Use of specific criminal acts to dehumanize the individual.,
            Public Sympathy: Minimization of public outrage by framing the individual as unworthy of sympathy.
        }
    },
    Legitimization of Police Actions: {
        Definition: The narrative rationalizes the use of force by law enforcement based on the perceived threat and noncompliance of the individual.,
        Subthemes: {
            Necessity of Force: Belief that the situation necessitated the use of lethal force.,
            Universal Response: Suggestion that anyone in a similar situation would have acted similarly.
        }
    },
    Resistance and Noncompliance: {
        Definition: The narrative emphasizes the individual's alleged refusal to comply with police orders, further justifying the police response.,
        Subthemes: {
            Alleged Noncompliance: Descriptions of the individual's refusal to follow police commands.,
            Consequences of Noncompliance: Linking noncompliance to the escalation of the situation.
        }
    },
    Evidence and Legitimization: {
        Definition: The narrative uses evidence, such as a recovered gun, to reinforce the justification of police actions and the individual's criminality.,
        Subthemes: {
            Physical Evidence: Presentation of material evidence to support the police account.,
            Narrative Reinforcement: Alignment of evidence with the broader narrative of criminality and danger.
        }
    }
}

# Theoretical Contextualization
theoretical_contextualization = {
    Critical Race Theory: Examines how race and racism intersect with power structures in society, influencing public and institutional responses to criminal incidents.,
    Narrative Frameworks: Analyzes how certain narratives are constructed and disseminated to justify or critique police actions, shaping public perception and discourse.
}

# Operationalizing Themes
operationalizing_themes = {
    Perceived Threat and Criminality: Identified by references to criminal history and immediate danger.,
    Racial Bias and Public Response: Evidenced by comparisons of public outrage across different racial groups and media influence.,
    Criminalization and Dehumanization: Marked by vilification and minimization of public sympathy.,
    Legitimization of Police Actions: Assessed through expressions of necessity and universality of the police response.,
    Resistance and Noncompliance: Determined by descriptions of alleged noncompliance and its consequences.,
    Evidence and Legitimization: Evidenced by the presentation and alignment of physical evidence with the narrative.
}
```

